mapper.sql:
SELECT s.PRODUCTION_ORDER_NO AS productionOrderNo, s.ASSEMBLY_MATERIAL_NO as assemblyMaterialNo, b.COMPONENT_MATERIAL_NO AS componentMaterialNo, e.MATERIAL_DESC AS materialDesc, s.SCHEDULED_QUANTITY AS orderQuantity, b.UNIT_USAGE AS unitUsage, s.SCHEDULED_QUANTITY * b.UNIT_USAGE AS totalRequirement, f.STOCK_QUANTITY AS stockQuantity, g.orderQuantity AS workInProgress, h.openPoQuantity AS openPoQuantity, s.SCHEDULED_DATE AS scheduledDate, s.BASIC_END_DATE AS basicEndDate, s.PRODUCTION_WORKSHOP AS productionWorkshop, e.PROCUREMENT_TYPE AS procurementType FROM SUB_ORDER s LEFT JOIN material_bom_import b ON s.ASSEMBLY_MATERIAL_NO = b.MAIN_MATERIAL_NO LEFT JOIN material_master_import e ON b.COMPONENT_MATERIAL_NO = e.MATERIAL_NO LEFT JOIN ( SELECT MATERIAL_NO, SUM(STOCK_QUANTITY) AS STOCK_QUANTITY FROM real_time_stock GROUP BY MATERIAL_NO ) f ON b.COMPONENT_MATERIAL_NO = f.MATERIAL_NO LEFT JOIN ( SELECT ASSEMBLY_MATERIAL_NO, SUM(SCHEDULED_QUANTITY - DELIVERED_QUANTITY) AS orderQuantity FROM SUB_ORDER WHERE SYSTEM_STATUS LIKE 'CRTD%' OR SYSTEM_STATUS LIKE 'REL%' GROUP BY ASSEMBLY_MATERIAL_NO ) g ON g.ASSEMBLY_MATERIAL_NO = b.COMPONENT_MATERIAL_NO LEFT JOIN ( SELECT MATERIAL_NO, SUM(ORDER_QTY - RECEIVED_QTY) AS openPoQuantity FROM BUYER_OPEN_ORDER GROUP BY MATERIAL_NO ) h ON h.MATERIAL_NO = b.COMPONENT_MATERIAL_NO WHERE s.DELETED = 0 AND b.COMPONENT_MATERIAL_NO IS NOT NULL
AND s.PRODUCTION_ORDER_NO = #{reqVO.productionOrderNo}
AND b.COMPONENT_MATERIAL_NO = #{reqVO.componentMaterialNo}
AND e.MATERIAL_DESC LIKE '%' || #{reqVO.materialDesc} || '%'
AND s.PRODUCTION_WORKSHOP = #{reqVO.productionWorkshop}
AND s.SCHEDULED_DATE >= #{reqVO.scheduledDateStart}
AND s.SCHEDULED_DATE <= #{reqVO.scheduledDateEnd}
AND s.BASIC_END_DATE >= #{reqVO.basicEndDateStart}
AND s.BASIC_END_DATE <= #{reqVO.basicEndDateEnd}
ORDER BY b.COMPONENT_MATERIAL_NO, s.SCHEDULED_DATE, s.SCHEDULED_QUANTITY

